-- ============================================================
-- V334: Danh mục nghề cho phỏng vấn theo nghề (19/10/2026, đợt 2a định hướng A + B + E)
--
-- Phủ mọi nghề bằng khung hai lớp: lớp chung (InterviewQuestionBank.commonQuestions) + lớp nghề.
-- Bảng này là danh mục; lớp câu hỏi theo nghề (AI tạo, có trạng thái duyệt) đến ở đợt 2b.
--
-- Nguồn: TỰ DỰNG. Không lấy nội dung BERUFENET — điều khoản BERUFENET (bản 09.11.2023) cấm dùng
-- nội dung để cung cấp lấy thù lao và cấm sửa nội dung (kể cả qua AI); xem quyết định 5 trong
-- plans/2026-10-18-quyet-dinh-dinh-huong-abe.md. Tên nghề tiếng Đức dùng dạng chuẩn hai giới
-- ("Koch/Köchin", "Pflegefachmann/-frau"); chưa ghi mã KldB/ISCO để tránh ghi mã sai.
--
-- legacy_persona_code + legacy_position_de: nghề trùng đúng một vị trí cũ trong
-- frontend/src/lib/personas.ts (labelDe) — nghề đó dùng bộ câu hỏi viết tay của nhân vật, và phiên
-- cũ (interview_position = labelDe) vẫn khớp được về nghề. Nghề không có nhân vật để NULL.
--
-- workplace: nhóm nơi làm việc — cơ sở cho "nhân vật theo nơi làm việc" (đợt 2c).
-- sort_rank: nhỏ = gợi ý trước (nghề phổ biến khi chưa gõ gì).
-- ============================================================

CREATE TABLE IF NOT EXISTS occupation (
    code                VARCHAR(64)  PRIMARY KEY,
    name_de             VARCHAR(160) NOT NULL,
    name_en             VARCHAR(160) NOT NULL,
    name_vi             VARCHAR(160) NOT NULL,
    workplace           VARCHAR(32)  NOT NULL,
    aliases             TEXT,
    legacy_persona_code VARCHAR(32),
    legacy_position_de  VARCHAR(100),
    sort_rank           INT          NOT NULL DEFAULT 1000,
    active              BOOLEAN      NOT NULL DEFAULT TRUE,
    created_at          TIMESTAMP    NOT NULL DEFAULT NOW(),
    updated_at          TIMESTAMP    NOT NULL DEFAULT NOW(),
    CONSTRAINT chk_occupation_workplace CHECK (workplace IN
        ('gastro', 'pflege', 'bau', 'industrie', 'logistik', 'handel', 'buero', 'bildung')),
    CONSTRAINT chk_occupation_legacy_pair CHECK ((legacy_persona_code IS NULL) = (legacy_position_de IS NULL))
);

CREATE INDEX IF NOT EXISTS idx_occupation_active_rank ON occupation (active, sort_rank);

ON CONFLICT (code) DO NOTHING;
